@@ -32,4 +32,24 @@
 <div class="mobile-nav" id="mobileNav"></div>
 <div class="landing" id="landing"><div class="landing-inner"><div><div class="brand"><div class="brand-mark">✦</div><div>TOKU<em style="color:var(--pink);font-style:normal">SENTAI</em>HERO</div></div><div class="landing-sub">SEU ESTÚDIO. SUA SÉRIE. SUAS REGRAS.</div><div class="landing-logo">CRIE SUA<br><span>PRÓPRIA</span><br>Lenda.</div><p class="landing-desc">Um estúdio Tokusatsu onde você escreve cada história, desenha cada herói e decide cada batalha. Não existe roteiro pronto. Só a sua imaginação.</p><div class="landing-actions"><button class="btn btn-primary" onclick="newSeries()">✦ Nova Série</button><button class="btn" id="continueBtn" onclick="continueSeries()">↻ Continuar Série</button></div><div class="landing-note">RPG TÁTICO · PIXEL ART 16-BIT · SALVAMENTO LOCAL</div></div><div class="landing-art"><div class="landing-sun">🦸</div></div></div></div>
 <div class="modal-backdrop" id="modalBackdrop" onclick="if(event.target===this)closeModal()"><div class="modal" id="modal"></div></div><div class="toast" id="toast"></div>
 <script>
+const KEY='tokusentaihero-v1';
+const blank=()=>({season:{name:'',theme:'',premise:'',style:'',base:'',villain:''},heroes:[],monsters:[],episodes:[],gear:[],mecha:{name:'',origin:'',design:'',finisher:''},tracks:[],credits:1200,progress:0});
+let data=blank(),currentView='home',activeAction='move',selectedId=null,round=1,teamTurn=true,battleUnits=[],musicOn=false,audioCtx=null,musicTimer=null,step=0,oscillators=[],battleDone=false,sceneTimer=null;
+const $=id=>document.getElementById(id),esc=s=>String(s||'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
+function loadData(){try{const x=JSON.parse(localStorage.getItem(KEY));if(x&&x.season)data={...blank(),...x}}catch(e){} updateUI()}
+function saveData(silent=false){if(!data.season.name){toast('Crie uma série antes de salvar.');return}localStorage.setItem(KEY,JSON.stringify(data));$('saveStatus').innerHTML='<i></i><span>SALVO AGORA</span>';if(!silent)toast('Série salva neste navegador ✓');updateUI()}
+function toast(msg){const t=$('toast');t.textContent=msg;t.classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>t.classList.remove('show'),2300)}
+function updateUI(){const active=!!data.season.name;$('topSeason').textContent=active?data.season.name.toUpperCase():'ESTÚDIO DE CRIAÇÃO';$('sideTitle').textContent=active?data.season.name:'Sua série começa aqui';$('sideTheme').textContent=active?(data.season.theme||'Tema em aberto'):'Crie um universo do zero';$('saveStatus').innerHTML=active?'<i></i><span>SÉRIE ATIVA</span>':'<i style="background:var(--muted)"></i><span>SEM SÉRIE ATIVA</span>';$('continueBtn').disabled=!active;$('continueBtn').style.opacity=active?'1':'.45';$('heroTitle').textContent=active?data.season.name:'Toda lenda começa com uma ideia.';$('heroDesc').textContent=active?(data.season.theme||data.season.premise||'Sua temporada está pronta para ganhar vida. Crie episódios e escolha o que acontece em cada cena.'):'Crie heróis, monstros, cenários e histórias. Escreva cada fala, decida cada acontecimento — este universo é todo seu.';$('heroAction').textContent=active?'Editar temporada →':'Começar a criar →';$('heroAction').onclick=()=>openSeason();$('statEpisodes').textContent=String(data.episodes.length).padStart(2,'0');$('statHeroes').textContent=String(data.heroes.length).padStart(2,'0');$('statMonsters').textContent=String(data.monsters.length).padStart(2,'0');$('statBudget').textContent=data.credits.toLocaleString('pt-BR');$('heroCount').textContent=data.heroes.length;$('monsterCount').textContent=data.monsters.length;$('rosterPrompt').style.display=data.heroes.length?'none':'block';$('dashboardRoster').innerHTML=data.heroes.slice(0,6).map(h=>`<div class="mini-hero" title="${esc(h.name)}">${esc(h.icon||'🦸')}</div>`).join('');let pct=data.episodes.length?Math.min(100,Math.round(data.episodes.filter(e=>e.done).length/Math.max(1,data.episodes.length)*100)):0;$('seasonProgress').style.width=pct+'%';$('progressText').textContent=`${pct}% DA TEMPORADA PRODUZIDA · ${data.episodes.filter(e=>e.done).length}/${data.episodes.length} CONCLUÍDOS`;renderDashboard();renderCast();renderEpisodes();renderGear();renderTracks();fillSeason();fillMecha();renderTeam();$('battleTitle').textContent=data.episodes.find(e=>e.active)?.setting||'Cenário: Praça urbana'}
+function showView(name){currentView=name;document.querySelectorAll('.view').forEach(v=>v.classList.toggle('active',v.id==='view-'+name));document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.view===name));if(name==='battle')renderBattle();if(name==='music')renderWave();window.scrollTo(0,0)}
+document.querySelectorAll('.nav-item').forEach(b=>b.onclick=()=>showView(b.dataset.view));
+function fillSeason(){const s=data.season;[['seasonName','name'],['seasonTheme','theme'],['seasonPremise','premise'],['seasonStyle','style'],['seasonBase','base'],['seasonVillain','villain']].forEach(([id,k])=>$(id).value=s[k]||'')}
+function saveSeason(){const old=data.season.name;data.season={name:$('seasonName').value.trim(),theme:$('seasonTheme').value.trim(),premise:$('seasonPremise').value.trim(),style:$('seasonStyle').value.trim(),base:$('seasonBase').value.trim(),villain:$('seasonVillain').value.trim()};if(!data.season.name){toast('Dê um nome à sua série.');return}localStorage.setItem(KEY,JSON.stringify(data));updateUI();$('landing').classList.remove('show');toast(old?'Identidade da temporada atualizada.':'Sua série nasceu! Progresso salvo.');showView('home')}
+function openSeason(){fillSeason();showView('season');$('landing').classList.remove('show')}
+function newSeries(){const saved=localStorage.getItem(KEY);if(saved&&confirm('Começar uma série nova? Isso substitui o save atual.')){data=blank();localStorage.removeItem(KEY)}else if(saved)return;else data=blank();$('landing').classList.remove('show');fillSeason();showView('season');toast('Comece dando um nome e tema à sua série.')}
+function continueSeries(){const saved=localStorage.getItem(KEY);if(!saved){toast('Nenhum save encontrado. Crie uma Nova Série!');return}loadData();$('landing').classList.remove('show');showView('home');toast('Série carregada. Bom trabalho, produtor!')}
+function deleteSave(){if(!localStorage.getItem(KEY)){toast('Não há save para excluir.');return}if(confirm('Excluir permanentemente o save desta série? Esta ação não pode ser desfeita.')){localStorage.removeItem(KEY);data=blank();updateUI();$('landing').classList.add('show');toast('Save excluído. Sua próxima série começa do zero.')}}
+$('saveBtn').onclick=()=>saveData();$('soundToggle').onclick=()=>toggleMusic();$('landing').classList.add('show');loadData();
+function renderDashboard(){const box=$('dashboardEpisodes');if(!data.episodes.length){box.innerHTML='<div class="empty">Ainda não há episódios. Sua sala de roteiro está em branco — crie o primeiro.</div>';return}box.innerHTML=data.episodes.slice(0,4).map((e,i)=>`<div class="episode-row"><div class="episode-no">${String(i+1).padStart(2,'0')}</div><div style="flex:1"><strong>${esc(e.title||'Episódio sem título')}</strong><span>${esc(e.setting||'Cenário não definido')} · ${e.scenes?.length||0} cenas</span></div><span class="ep-state">${e.done?'CONCLUÍDO':'EM ROTEIRO'}</span></div>`).join('')}
+function renderCast(){const list=(arr,type)=>arr.length?arr.map(c=>`<div class="item-card"><div class="item-icon">${esc(c.icon|| (type==='hero'?'🦸':'👾'))}</div><div style="min-width:0"><strong>${esc(c.name)}</strong><p>${esc(c.role||c.power||'Sem descrição')} · ${esc(c.color||'cor livre')}</p></div><span class="badge">${type==='hero'?'HERÓI':'MONSTRO'} · HP ${c.hp||100}</span><div class="inline-actions"><button class="btn btn-small" onclick="editCharacter('${type}','${c.id}')">Editar</button><button class="btn btn-danger btn-small" onclick="removeCharacter('${type}','${c.id}')">×</button></div></div>`).join(''):'<div class="empty">Nenhuma criação ainda. Use os botões acima para dar vida ao seu elenco.</div>';$('heroList').innerHTML=list(data.heroes,'hero');$('monsterList').innerHTML=list(data.monsters,'monster')}
+function uid(){return Math.random().toString(36).slice(2,9)}

input.newString:
function uid(){return Math.random().toString(36).slice(2,9)}
function modalOpen(html){$('modal').innerHTML=html;$('modalBackdrop').classList.add('show')}
function closeModal(){ $('modalBackdrop').classList.remove('show') }
function openCharacter(type,id=''){const arr=type==='hero'?data.heroes:data.monsters,old=arr.find(x=>x.id===id)||{};const monster=type==='monster';modalOpen(`<div class="modal-head"><div><div class="eyebrow">${monster?'CRIATURA DO DIA':'PROTAGONISTA'}</div><h2>${id?'Editar':'Criar'} ${monster?'monstro':'herói'}</h2><p>Personalize identidade, visual e habilidades.</p></div><button class="close" onclick="closeModal()">×</button></div><div class="form-grid"><div class="field"><label>NOME</label><input id="cName" value="${esc(old.name)}" placeholder="Nome da personagem"></div><div class="field"><label>ÍCONE / EMOJI DO SPRITE</label><input id="cIcon" value="${esc(old.icon||'')}" placeholder="🦸" maxlength="6"></div><div class="field"><label>${monster?'PAPEL / NATUREZA':'IDENTIDADE / PAPEL NA EQUIPE'}</label><input id="cRole" value="${esc(old.role||'')}" placeholder="Descreva em poucas palavras"></div><div class="field"><label>HABILIDADE / PODER</label><input id="cPower" value="${esc(old.power||'')}" placeholder="O que esta criação consegue fazer?"></div><div class="field"><label>COR PRINCIPAL</label><input id="cColor" value="${esc(old.color||'')}" placeholder="Ex.: azul elétrico"></div><div class="field"><label>PONTOS DE VIDA</label><input id="cHp" type="number" min="30" max="200" value="${old.hp||100}"></div><div class="field full"><label>HISTÓRIA, PERSONALIDADE & DESIGN</label><textarea id="cBio" placeholder="Escreva tudo que quiser sobre esta criação…">${esc(old.bio||'')}</textarea></div></div><div class="modal-foot"><span style="font:9px var(--mono);color:var(--muted)">A criação é sua. Não há classes obrigatórias.</span><button class="btn btn-primary" onclick="saveCharacter('${type}','${id}')">Salvar criação</button></div>`)}
function saveCharacter(type,id){const c={id:id||uid(),name:$('cName').value.trim(),icon:$('cIcon').value.trim()||(type==='hero'?'🦸':'👾'),role:$('cRole').value.trim(),power:$('cPower').value.trim(),color:$('cColor').value.trim(),hp:Math.min(200,Math.max(30,+$('cHp').value||100)),bio:$('cBio').value.trim()};if(!c.name){toast('Toda criação precisa de um nome.');return}const arr=type==='hero'?data.heroes:data.monsters;const i=arr.findIndex(x=>x.id===id);if(i<0)arr.push(c);else arr[i]=c;closeModal();commit('Criação adicionada ao elenco.');}
function editCharacter(type,id){openCharacter(type,id)}function removeCharacter(type,id){if(!confirm('Remover esta criação do elenco?'))return;const arr=type==='hero'?data.heroes:data.monsters;const i=arr.findIndex(x=>x.id===id);if(i>=0)arr.splice(i,1);commit('Criação removida.')}
function commit(msg){localStorage.setItem(KEY,JSON.stringify(data));updateUI();toast(msg)}
function openEpisode(id=''){const old=data.episodes.find(e=>e.id===id)||{};const scenes=old.scenes?.length?old.scenes:[{title:'Cena 1 — Abertura',place:'',description:'',dialogues:'',event:''}];modalOpen(`<div class="modal-head"><div><div class="eyebrow">ROTEIRO ABERTO · ${id?'EDIÇÃO':'NOVO EPISÓDIO'}</div><h2>${id?'Reescreva':'Escreva'} seu episódio</h2><p>Você decide o que acontece. Adicione cenas e diálogos sem limite.</p></div><button class="close" onclick="closeModal()">×</button></div><div class="form-grid"><div class="field"><label>TÍTULO DO EPISÓDIO</label><input id="eTitle" value="${esc(old.title||'')}" placeholder="Ex.: O eco das estrelas"></div><div class="field"><label>CENÁRIO PRINCIPAL</label><input id="eSetting" value="${esc(old.setting||'')}" placeholder="Ex.: estação orbital abandonada"></div><div class="field full"><label>ENREDO / SINOPSE — DIGITE DO ZERO</label><textarea id="eSynopsis" placeholder="O que acontece neste episódio? Qual conflito, surpresa ou emoção?">${esc(old.synopsis||'')}</textarea></div><div class="field full"><label>ANOTAÇÕES DE DIREÇÃO / ATMOSFERA</label><input id="eDirection" value="${esc(old.direction||'')}" placeholder="Paleta, clima, ritmo, referência visual…"></div></div><div class="section-head"><h3>Cenas & acontecimentos</h3><button class="btn btn-small btn-cyan" onclick="addSceneForm()">＋ Adicionar cena</button></div><div id="sceneForms">${scenes.map(sceneMarkup).join('')}</div><div class="field" style="margin-top:13px"><label>TRILHA / MÚSICA DESTE EPISÓDIO</label><input id="eMusic" value="${esc(old.music||'')}" placeholder="Faixa, clima ou instrução sonora"></div><div class="modal-foot"><label style="font-size:10px;color:var(--muted)"><input type="checkbox" id="eDone" ${old.done?'checked':''}> Marcar como episódio produzido</label><button class="btn btn-primary" onclick="saveEpisode('${id}')">Salvar episódio</button></div>`)}
function sceneMarkup(s={}){return `<div class="card scene-form" style="margin-bottom:10px;padding:13px"><div class="form-grid"><div class="field"><label>TÍTULO DA CENA</label><input class="sc-title" value="${esc(s.title||'')}" placeholder="Cena 1 — Encontro"></div><div class="field"><label>LOCAL / CENÁRIO</label><input class="sc-place" value="${esc(s.place||'')}" placeholder="Onde acontece?"></div><div class="field full"><label>DESCRIÇÃO VISUAL & AÇÃO</label><textarea class="sc-description" placeholder="O que aparece e acontece nesta cena?">${esc(s.description||'')}</textarea></div><div class="field full"><label>DIÁLOGOS (um por linha: PERSONAGEM: fala)</label><textarea class="sc-dialogues" placeholder="AIRA: Não vamos recuar!\nNARRADOR: O céu se ilumina.">${esc(s.dialogues||'')}</textarea></div><div class="field full"><label>EVENTO / ESCOLHA / BATALHA DESTA CENA</label><input class="sc-event" value="${esc(s.event||'')}" placeholder="Ex.: perseguição, transformação, reviravolta…"></div></div><button class="text-link" style="margin-top:8px;color:#ff879b" onclick="this.closest('.scene-form').remove()">Remover cena ×</button></div>`}
function addSceneForm(){const box=$('sceneForms');box.insertAdjacentHTML('beforeend',sceneMarkup({title:`Cena ${box.children.length+1}`}))}
function saveEpisode(id){const e={id:id||uid(),title:$('eTitle').value.trim(),setting:$('eSetting').value.trim(),synopsis:$('eSynopsis').value.trim(),direction:$('eDirection').value.trim(),music:$('eMusic').value.trim(),done:$('eDone').checked,scenes:[...document.querySelectorAll('.scene-form')].map(s=>({title:s.querySelector('.sc-title').value,place:s.querySelector('.sc-place').value,description:s.querySelector('.sc-description').value,dialogues:s.querySelector('.sc-dialogues').value,event:s.querySelector('.sc-event').value}))};if(!e.title){toast('Dê um título ao episódio.');return}const i=data.episodes.findIndex(x=>x.id===id);if(i<0)data.episodes.push(e);else data.episodes[i]=e;if(e.done)data.credits=Math.max(0,data.credits-50);closeModal();commit('Episódio salvo no roteiro.');}
function renderEpisodes(){const list=$('episodeList');if(!data.episodes.length){list.innerHTML='<div class="empty">O roteiro ainda está em branco. Crie seu primeiro episódio para começar a temporada.</div>';return}list.innerHTML=data.episodes.map((e,i)=>`<div class="item-card"><div class="episode-no">${String(i+1).padStart(2,'0')}</div><div style="flex:1"><strong>${esc(e.title)}</strong><p>${esc(e.setting||'Cenário livre')} · ${e.scenes?.length||0} cenas · ${e.done?'Produzido':'Em roteiro'}</p><p style="margin-top:7px">${esc(e.synopsis||'Sem sinopse ainda')}</p></div><span class="badge">${e.done?'FINALIZADO':'RASCUNHO'}</span><div class="inline-actions"><button class="btn btn-small btn-cyan" onclick="runEpisode('${e.id}')">▶ Cena</button><button class="btn btn-small" onclick="openEpisode('${e.id}')">Editar</button><button class="btn btn-danger btn-small" onclick="removeEpisode('${e.id}')">×</button></div></div>`).join('')}
function removeEpisode(id){if(confirm('Excluir este episódio?')){data.episodes=data.episodes.filter(e=>e.id!==id);commit('Episódio removido.')}}

