const scale=[0,2,4,7,9,12,16,19],darkScale=[0,3,5,7,10,12,15,17];
function playTone(freq,duration,type='sawtooth',gain=.045,when=0){if(!audioCtx)return;const osc=audioCtx.createOscillator(),amp=audioCtx.createGain();osc.type=type;osc.frequency.value=freq;amp.gain.setValueAtTime(0,audioCtx.currentTime+when);amp.gain.linearRampToValueAtTime(gain,audioCtx.currentTime+when+.012);amp.gain.exponentialRampToValueAtTime(.001,audioCtx.currentTime+when+duration);osc.connect(amp);amp.connect(audioCtx.destination);osc.start(audioCtx.currentTime+when);osc.stop(audioCtx.currentTime+when+duration+.03)}
