function playCutscene(ep){const episode=ep||data.episodes.find(e=>e.id===data.episodes.find(x=>x.active)?.id)||data.episodes[0];let lines=[];if(episode?.scenes?.length){episode.scenes.forEach((s,i)=>{const raw=(s.dialogues||'').split('\n').map(x=>x.trim()).filter(Boolean);if(raw.length)raw.forEach(line=>{const parts=line.split(':');lines.push({speaker:parts.length>1?parts.shift().trim():`CENA ${i+1}`,text:parts.join(':').trim()||line,scene:s})});else lines.push({speaker:s.title||`CENA ${i+1}`,text:s.description||s.event||'A cena se desenrola. O que acontece a seguir está nas suas mãos.',scene:s});if(s.event)lines.push({speaker:'ACONTECIMENTO',text:s.event,scene:s})})}else lines=[{speaker:data.season.name||'TOKUSENTAIHERO',text:data.season.premise||'A tela se ilumina. Um novo universo está prestes a ser criado. Qual será a primeira história?',scene:{}}];let ix=0;function show(){if(ix>=lines.length){closeModal();return}const line=lines[ix],scene=line.scene||{};$('modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">CUTSCENE ANIMADA · ${esc(episode?.title||data.season.name||'ABERTURA')}</div><h2 style="margin:5px 0">${esc(scene.title||'Sequência de abertura')}</h2></div><button class="close" onclick="closeModal()">×</button></div><div class="cutscene-art"><div class="sun"></div><div class="scene-sil">${esc(data.heroes[0]?.icon||'🦸')}</div><div class="scene-sil monster">${esc(data.monsters[0]?.icon||'👾')}</div><div class="scene-lines"></div></div><div style="font:9px var(--mono);color:var(--muted);margin-bottom:8px">${esc(scene.place||episode?.setting||'CENÁRIO DEFINIDO PELO PRODUTOR')}</div><div class="dialogue-box"><div class="speaker">${esc(line.speaker)}</div><div class="dialogue-text">${esc(line.text)}</div></div><div class="modal-foot"><span style="font:9px var(--mono);color:var(--muted)">${ix+1} / ${lines.length} · CENA ANIMADA</span><div class="inline-actions"><button class="btn btn-small" onclick="closeModal()">Pular</button><button class="btn btn-primary" onclick="window.cutNext()">${ix===lines.length-1?'Concluir':'Próximo →'}</button></div></div>`;}
window.cutNext=()=>{ix++;show()};modalOpen('<div></div>');show()}
function runEpisode(id){const e=data.episodes.find(x=>x.id===id);if(!e)return;data.episodes.forEach(x=>x.active=false);e.active=true;localStorage.setItem(KEY,JSON.stringify(data));updateUI();playCutscene(e)}
function logBattle(msg,kind=''){const l=$('battleLog');l.insertAdjacentHTML('afterbegin',`<p class="${kind}">› ${esc(msg)}</p>`);while(l.children.length>24)l.lastChild.remove()}
function resetBattle(){round=1;teamTurn=true;battleDone=false;activeAction='move';selectedId=null;const heroSource=data.heroes.length?data.heroes.slice(0,3):[{id:'demo-h1',name:'Sentinela Rubra',icon:'🦸',hp:100,power:'Impacto heroico'},{id:'demo-h2',name:'Guardiã Prisma',icon:'🦸‍♀️',hp:100,power:'Raio prisma'}];const enemySource=data.monsters.length?data.monsters.slice(0,3):[{id:'demo-m1',name:'Golem de Sucata',icon:'👾',hp:100,power:'Golpe pesado'},{id:'demo-m2',name:'Vulto Neon',icon:'👹',hp:80,power:'Investida'}];battleUnits=[...heroSource.map((h,i)=>({id:'h-'+h.id,name:h.name,icon:h.icon||'🦸',team:'hero',hp:+h.hp||100,max:+h.hp||100,x:1,y:i+1,power:h.power||'Ataque',acted:false})),...enemySource.map((m,i)=>({id:'m-'+m.id,name:m.name,icon:m.icon||'👾',team:'enemy',hp:Math.min(120,+m.hp||90),max:Math.min(120,+m.hp||90),x:7,y:i+1,power:m.power||'Golpe',acted:false}))];$('battleLog').innerHTML='';logBattle('Combate iniciado. Comande seus heróis, depois os monstros agirão.','good');renderBattle()}
function renderTeam(){$('teamStrip').innerHTML=battleUnits.filter(u=>u.team==='hero').map(u=>`<div class="team-unit ${u.id===selectedId?'active':''}" onclick="selectUnit('${u.id}')" title="${esc(u.name)}">${esc(u.icon)}<small>${esc(u.name.slice(0,9))} · ${u.hp}/${u.max}</small></div>`).join('')}
function renderBattle(){if(!battleUnits.length)resetBattle();const grid=$('battleGrid');grid.innerHTML='';const blocks=[[4,1],[4,4],[5,2],[5,3]];for(let y=0;y<6;y++)for(let x=0;x<9;x++){const u=battleUnits.find(a=>a.hp>0&&a.x===x&&a.y===y),tile=document.createElement('div');tile.className='tile'+(u?.team==='enemy'?' enemy':'')+(blocks.some(b=>b[0]===x&&b[1]===y)?' terrain':'');tile.dataset.x=x;tile.dataset.y=y;if(u){tile.innerHTML=`${esc(u.icon)}<span class="hp-mini"><i style="width:${Math.max(0,100*u.hp/u.max)}%"></i></span>`;if(u.id===selectedId)tile.classList.add('actor-selected')}tile.onclick=()=>tileClick(x,y);grid.appendChild(tile)}$('turnBadge').textContent=battleDone?'COMBATE CONCLUÍDO':teamTurn?'TURNO DO JOGADOR':'TURNO DOS MONSTROS';$('turnBadge').style.color=teamTurn?'var(--cyan)':'var(--red)';$('battleRound').textContent=`RODADA ${round}`;renderTeam();renderUnitInfo();document.querySelectorAll('.action').forEach(b=>b.classList.toggle('selected',b.dataset.action===activeAction));}
function renderUnitInfo(){const u=battleUnits.find(x=>x.id===selectedId);if(!u){$('unitStats').innerHTML='<div class="empty">Selecione uma unidade para ver seus dados.</div>';return}$('unitStats').innerHTML=`<div class="unit-info"><div class="unit-avatar">${esc(u.icon)}</div><div><strong>${esc(u.name)}</strong><span>${u.team==='hero'?'HERÓI':'MONSTRO'} · ${u.acted?'AÇÃO USADA':'PRONTO'}</span></div></div><div class="hp-bar"><i style="width:${Math.max(0,100*u.hp/u.max)}%"></i></div><div class="hp-text">HP ${u.hp} / ${u.max} · ${esc(u.power)}</div>`}
function selectUnit(id){const u=battleUnits.find(x=>x.id===id);if(!u||u.hp<=0)return;if(teamTurn&&u.team!=='hero')return;selectedId=id;renderBattle()}
function setAction(action){activeAction=action;document.querySelectorAll('.action').forEach(b=>b.classList.toggle('selected',b.dataset.action===action));}
function dist(a,x,y){return Math.abs(a.x-x)+Math.abs(a.y-y)}
function tileClick(x,y){if(battleDone||!teamTurn)return;const occupant=battleUnits.find(u=>u.hp>0&&u.x===x&&u.y===y);if(occupant){if(occupant.team==='hero'){selectUnit(occupant.id);return}if(activeAction==='attack'||activeAction==='skill'){performAttack(occupant);return}return}const unit=battleUnits.find(u=>u.id===selectedId&&u.hp>0);if(!unit||unit.team!=='hero'){toast('Selecione um herói para agir.');return}if(unit.acted){toast('Este herói já usou sua ação nesta rodada.');return}if(activeAction==='move'){if(dist(unit,x,y)>2){toast('Movimento limitado a 2 casas.');return}if(blocksTile(x,y)){toast('Há cobertura neste espaço.');return}unit.x=x;unit.y=y;unit.acted=true;logBattle(`${unit.name} se move para uma posição tática.`,'good');renderBattle()}else if(activeAction==='wait'){unit.acted=true;logBattle(`${unit.name} aguarda e mantém posição.`);renderBattle()}else if(activeAction==='attack'||activeAction==='skill')toast('Selecione um monstro ao alcance para atacar.')}
function blocksTile(x,y){return [[4,1],[4,4],[5,2],[5,3]].some(a=>a[0]===x&&a[1]===y)}
function performAttack(enemy){const actor=battleUnits.find(u=>u.id===selectedId&&u.hp>0);if(!actor||actor.team!=='hero'){toast('Selecione um herói.');return}if(actor.acted){toast('Este herói já agiu nesta rodada.');return}const range=activeAction==='skill'?3:1;if(dist(actor,enemy.x,enemy.y)>range){toast(`Fora de alcance (${range} casas).`);return}const damage=activeAction==='skill'?34:22;enemy.hp=Math.max(0,enemy.hp-damage);actor.acted=true;logBattle(`${actor.name} usa ${activeAction==='skill'?'especial':'ataque'} em ${enemy.name}: −${damage} HP.`, 'good');if(enemy.hp<=0){logBattle(`${enemy.name} foi derrotado!`,'good');if(battleUnits.filter(u=>u.team==='enemy'&&u.hp>0).length===0){battleDone=true;data.credits+=150;logBattle('Vitória! +150 créditos de produção.','good');localStorage.setItem(KEY,JSON.stringify(data));toast('Vitória! +150 créditos.')}}renderBattle()}
function finishTurn(){if(battleDone)return;if(!teamTurn){toast('Os monstros ainda estão agindo.');return}teamTurn=false;activeAction='move';$('turnBadge').textContent='TURNO DOS MONSTROS';renderBattle();logBattle('Turno dos monstros. Eles avançam!','bad');let enemies=battleUnits.filter(u=>u.team==='enemy'&&u.hp>0),index=0;function act(){if(index>=enemies.length){teamTurn=true;round++;battleUnits.filter(u=>u.team==='hero').forEach(u=>u.acted=false);battleUnits.filter(u=>u.team==='enemy').forEach(u=>u.acted=false);selectedId=battleUnits.find(u=>u.team==='hero'&&u.hp>0)?.id||null;if(battleUnits.filter(u=>u.team==='hero'&&u.hp>0).length===0){battleDone=true;logBattle('Equipe derrotada. Reinicie o combate para tentar de novo.','bad')}renderBattle();return}const enemy=enemies[index++];if(enemy.hp<=0){setTimeout(act,250);return}const heroes=battleUnits.filter(u=>u.team==='hero'&&u.hp>0);if(!heroes.length){setTimeout(act,250);return}heroes.sort((a,b)=>dist(enemy,a.x,a.y)-dist(enemy,b.x,b.y));const target=heroes[0];if(dist(enemy,target.x,target.y)>1){const opts=[[enemy.x+Math.sign(target.x-enemy.x),enemy.y],[enemy.x,enemy.y+Math.sign(target.y-enemy.y)]];const step=opts.find(p=>p[0]>=0&&p[0]<9&&p[1]>=0&&p[1]<6&&!blocksTile(...p)&&!battleUnits.some(u=>u.hp>0&&u.x===p[0]&&u.y===p[1]));if(step){enemy.x=step[0];enemy.y=step[1];logBattle(`${enemy.name} avança pela arena.`,'bad')}}if(dist(enemy,target.x,target.y)<=1){const damage=14+Math.floor(Math.random()*9);target.hp=Math.max(0,target.hp-damage);logBattle(`${enemy.name} ataca ${target.name}: −${damage} HP.`,'bad');if(target.hp===0)logBattle(`${target.name} caiu!`,'bad')}renderBattle();setTimeout(act,450)}setTimeout(act,350)}

