$('saveBtn').addEventListener('click',()=>{if(data.season.name)saveData()});window.addEventListener('beforeunload',()=>{if(data.season.name)localStorage.setItem(KEY,JSON.stringify(data))});window.addEventListener('keydown',e=>{if(e.key==='Escape')closeModal()});
